pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 oldPID, uint256 newPID) public {
        // Bound inputs to avoid unrealistic values
        vm.assume(oldPID > 0 && oldPID <= 100);
        vm.assume(newPID > 0 && newPID <= 100);
        vm.assume(oldPID != newPID);

        // Create two proposals to set up the state
        c.newGrantProposal(address(0x1234), 100); // proposalCount becomes 1 (or 2 in buggy version)
        c.newGrantProposal(address(0x5678), 200); // proposalCount becomes 2 (or 4 in buggy version)

        // Need to finalise the old proposal to make cancelProposal possible
        // But finaliseProposal requires mapping to exist. We'll use voteProposal first
        // Simulate: we need to make oldPID finalising. We'll call voteProposal to trigger _finalise
        // But the contract logic requires quorum etc. For simplicity, we directly check
        // The property: cancelProposal should not change proposalCount

        // Record proposalCount before cancel
        uint countBefore = c.proposalCount();

        // We'll catch revert if cancelProposal fails
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.cancelProposal.selector, oldPID, newPID)
        );

        // After cancel, proposalCount should remain unchanged (equal to countBefore)
        uint countAfter = c.proposalCount();
        assertTrue(countAfter == countBefore, "cancelProposal should not change proposalCount");
    }
}

