pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oldProposalID, uint256 newProposalID, address recipient, uint256 amount) public {
        // Use vm.assume to ensure we can create at least two proposals of the same type (GRANT) to satisfy cancelProposal requirements
        vm.assume(oldProposalID != newProposalID);
        // Create a grant proposal to get a proposal ID (assumes proposalCount starts at 0)
        c.newGrantProposal(recipient, amount);
        uint256 firstProposalID = 1; // After first call, proposalCount becomes 1 (or 2 in mutant)
        // Create another grant proposal
        c.newGrantProposal(recipient, amount);
        uint256 secondProposalID = firstProposalID + 1; // In reference: 2, in mutant: 3
        // To call cancelProposal, the old proposal must be "finalising" (hasMajority and not yet finalised)
        // and the new proposal must have minority. For simplicity, we assume the environment allows this.
        // We'll use a try/catch to call cancelProposal and check the state after
        uint256 countBefore = c.proposalCount();
        bool reverted = false;
        try c.cancelProposal(oldProposalID, newProposalID) {
            // success
        } catch {
            reverted = true;
        }
        uint256 countAfter = c.proposalCount();
        // The rule: cancelProposal should NOT change proposalCount
        assertTrue(reverted || countAfter == countBefore, "cancelProposal should keep proposalCount unchanged or revert");
    }
