pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address proposer1,
        address proposer2,
        address proposedAddress,
        string memory typeStr,
        uint256 oldProposalID,
        uint256 newProposalID
    ) public {
        // Ensure typeStr is one of the supported types (DAO, UTILS, REWARD, GRANT)
        vm.assume(keccak256(bytes(typeStr)) == keccak256(bytes("DAO")) || keccak256(bytes(typeStr)) == keccak256(bytes("UTILS")) || keccak256(bytes(typeStr)) == keccak256(bytes("REWARD")) || keccak256(bytes(typeStr)) == keccak256(bytes("GRANT")));
        // Ensure proposers are distinct and non-zero
        vm.assume(proposer1 != address(0) && proposer2 != address(0) && proposer1 != proposer2);
        // Ensure proposed address is non-zero for non-GRANT proposals
        vm.assume(proposedAddress != address(0));
        // Bind proposal IDs to be non-zero and different
        oldProposalID = bound(oldProposalID, 1, 100);
        newProposalID = bound(newProposalID, 1, 100);
        vm.assume(oldProposalID != newProposalID);

        // Set up by creating two proposals (old and new) with the same type
        // First proposal (old) - we'll use the known proposalCount to match oldProposalID
        vm.prank(proposer1);
        if (keccak256(bytes(typeStr)) == keccak256(bytes("GRANT"))) {
            c.newGrantProposal(address(0xdead), 100); // GRANT uses newGrantProposal
        } else {
            c.newAddressProposal(proposedAddress, typeStr);
        }
        // Get the actual proposal ID
        uint256 actualOldID = c.proposalCount();

        // Second proposal (new) with same type
        vm.prank(proposer2);
        if (keccak256(bytes(typeStr)) == keccak256(bytes("GRANT"))) {
            c.newGrantProposal(address(0xbeef), 200);
        } else {
            c.newAddressProposal(proposedAddress, typeStr);
        }
        uint256 actualNewID = c.proposalCount();

        // Need to make the old proposal finalising so cancelProposal works
        // This requires triggering finalising via voteProposal with quorum
        // For simplicity, we assume the contract has some pre-set vault that returns weights
        // Since we can't set up the vault, we'll use an approach that works with the actual deployment
        // The test will attempt to call cancelProposal and check the rule

        // Attempt to finalise the old proposal by calling voteProposal (may fail if no vault)
        (bool success, ) = address(c).call(abi.encodeWithSignature("voteProposal(uint256)", actualOldID));

        // Only test if we can get to a state where mapPID_finalising[actualOldID] is true
        // We'll try to make it finalising by directly setting (not possible via public)
        // Instead, rely on the fact that the bug affects mapPID_address regardless of finalising

        // Record address before cancel for old proposal
        address oldAddrBefore;
        if (keccak256(bytes(typeStr)) != keccak256(bytes("GRANT"))) {
            oldAddrBefore = c.mapPID_address(actualOldID);
        }

        // Try to call cancelProposal (will revert if conditions not met, but we can still check storage)
        (bool cancelSuccess, ) = address(c).call(abi.encodeWithSignature("cancelProposal(uint256,uint256)", actualOldID, actualNewID));

        // Rule: After cancelProposal, if the proposal type is not GRANT, the old proposal's address should be zero
        // The bug sets mapPID_address[proposalCount] = address(0) during newAddressProposal, overwriting the proposed address

        if (keccak256(bytes(typeStr)) != keccak256(bytes("GRANT")) && oldProposalID == actualOldID && newProposalID == actualNewID) {
            // The reference would keep the non-zero address, the mutant would have set it to zero
            // Since the bug only affects the newly created proposal, the old proposal's address is not directly affected
            // But the invariant we want: for proposals of type != GRANT, mapPID_address[proposalID] should not be zero
            address oldAddrAfter = c.mapPID_address(actualOldID);
            // The rule: old proposal's address should be non-zero (since it was created before the buggy call)
            assertTrue(oldAddrAfter != address(0));
        }
    }
}
